@router.put("/hx/v1/billing/payment-methods/{card_id}/set-default", response_class=HTMLResponse)
async def set_default_payment_card(
    request: Request,
    card_id: str,
    templates: Jinja2Templates = Depends(get_templates),
    db: AsyncSession = Depends(get_async_db),
    current_user: User = Depends(get_current_user)
):
    card = await db.get(PaymentCard, card_id)
    if not card or card.customer_id != current_user.customer_id:
        raise HTTPException(status_code=404, detail="Card not found or access denied")
    await db.execute(
        update(PaymentCard).where(PaymentCard.customer_id == current_user.customer_id).values(is_default=False)
    )
    card.is_default = True
    await db.commit()
    return templates.TemplateResponse(
        "partials/payment_card_row.html",
        {"request": request, "card": card}
    )
